export interface IconProps extends SVGProps<SVGSVGElement> {
  /** Which icon to render. */
  name: IconName;
  /** Width/height in px. Defaults to 20. */
  size?: number;
  /**
   * Accessible name for the icon. Omit for purely decorative icons
   * (the default) — the icon is then hidden from assistive tech.
   */
  title?: string;
}

export function Icon({ name, size = 20, title, ...props }: IconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
      {...props}
    >
      {title ? <title>{title}</title> : null}
      {ICON_PATHS[name]}
    </svg>
  );
}
